import json, numpy as np
from a vision library.core.calibration import CameraCalibration, CameraModelType
from a vision library.core.sophus import SE3

_cams=json.load(open('materials/cameras.json'))
def build(clip):
    c=_cams[clip]; params=np.array(c['projectionParams'])
    q=c['T_Device_Camera']['quaternion_wxyz']; t=c['T_Device_Camera']['translation_xyz']
    T=SE3.from_quat_and_translation(q[0],np.array(q[1:]),np.array(t))
    return CameraCalibration("camera-rgb",CameraModelType.a camera model,params,T,1408,1408,None,1.0,"sn")

def ray(cc,px):
    """unit ray direction in camera frame for a pixel"""
    d=cc.unproject(np.array(px,dtype=float))
    d=np.array(d,dtype=float); return d/np.linalg.norm(d)

def angle_between_px(cc,p1,p2):
    r1=ray(cc,p1); r2=ray(cc,p2)
    return np.arccos(np.clip(r1@r2,-1,1))

def range_from_size(cc,p1,p2,phys_m):
    """range to midpoint given two endpoints separated by phys_m along a fronto-parallel-ish segment"""
    th=angle_between_px(cc,p1,p2)
    # chord: phys = 2*R*sin(th/2)  => R = phys/(2 sin(th/2))
    return phys_m/(2*np.sin(th/2))

def t_from_centroid(cc,px,rng):
    r=ray(cc,px); return r*rng

def quat_from_R(R):
    # R (3x3) -> wxyz
    m=R; tr=m[0,0]+m[1,1]+m[2,2]
    if tr>0:
        S=np.sqrt(tr+1)*2; w=0.25*S; x=(m[2,1]-m[1,2])/S; y=(m[0,2]-m[2,0])/S; z=(m[1,0]-m[0,1])/S
    elif m[0,0]>m[1,1] and m[0,0]>m[2,2]:
        S=np.sqrt(1+m[0,0]-m[1,1]-m[2,2])*2; w=(m[2,1]-m[1,2])/S; x=0.25*S; y=(m[0,1]+m[1,0])/S; z=(m[0,2]+m[2,0])/S
    elif m[1,1]>m[2,2]:
        S=np.sqrt(1+m[1,1]-m[0,0]-m[2,2])*2; w=(m[0,2]-m[2,0])/S; x=(m[0,1]+m[1,0])/S; y=0.25*S; z=(m[1,2]+m[2,1])/S
    else:
        S=np.sqrt(1+m[2,2]-m[0,0]-m[1,1])*2; w=(m[1,0]-m[0,1])/S; x=(m[0,2]+m[2,0])/S; y=(m[1,2]+m[2,1])/S; z=0.25*S
    q=np.array([w,x,y,z]); return q/np.linalg.norm(q)

def R_from_axes(zc, yc):
    """Build rotation whose object +Z maps to cam dir zc, object +Y ~ yc. columns = object axes in cam frame."""
    z=np.array(zc,float); z/=np.linalg.norm(z)
    y=np.array(yc,float); y=y-(y@z)*z; 
    if np.linalg.norm(y)<1e-6: y=np.array([0,1,0.])-((np.array([0,1,0.]))@z)*z
    y/=np.linalg.norm(y)
    x=np.cross(y,z); x/=np.linalg.norm(x)
    R=np.column_stack([x,y,z]); return R
